export class ActivationHelper {
    /**
     * Returns the license key from hypertube.lic, falling back to the key
     * configured through RuntimeBridge or a configuration file.
     * @returns {string}
     */
    static getLicenseKey(): string;
    /**
     * Reads the license key from hypertube.lic in the SDK working directory.
     * Both the XML license format and the JSON format used by some SDK versions
     * are supported.
     * @returns {string}
     */
    static getLicenseKeyFromFile(): string;
    /**
     * @param {string} contents
     * @returns {string}
     */
    static "__#private@#getLicenseKeyFromJson"(contents: string): string;
    /**
     * @param {string} contents
     * @returns {string}
     */
    static "__#private@#getLicenseKeyFromXml"(contents: string): string;
    /**
     * @param {string} value
     * @returns {string}
     */
    static "__#private@#decodeXml"(value: string): string;
}
